func:
// Merkt sich die Stationsliste (.../static/stations, retained).
// Routen, die vorher eingetroffen sind, werden jetzt nachträglich verarbeitet.
const list = Array.isArray(msg.payload) ? msg.payload : [];
const map = {};
for (const s of list) map[s.id] = s;
flow.set('stations', map);
node.status({ fill: 'green', shape: 'dot', text: list.length + ' Stationen bekannt' });
const pending = flow.get('pending') || {};
flow.set('pending', {});
return [Object.values(pending)];

// Merkt sich, für welche Routen schon ein Profil existiert (retained).
// So wird nach einem Neustart nicht jede Route erneut bei ORS angefragt.
const cfg = global.get('cfg');
// Zustand verwerfen, wenn sich das Präfix geändert hat (Context überlebt einen Deploy)
let cache = flow.get('profiles');
if (!cache || cache.__prefix !== cfg.prefix) cache = { __prefix: cfg.prefix };
const key = msg.topic.split('/').slice(-2).join('/');
const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty) delete cache[key];
else if (typeof msg.payload === 'object') cache[key] = msg.payload.orsError ? null : msg.payload.routeHash;
flow.set('profiles', cache);
return null;

// Eingang für Routen: .../routes/<nutzer>/<route-id>
// Payload: {"name":"Zur Uni","from":{"label":"Calle de Alcalá 50","lat":40.42,"lon":-3.69},"to":{...}}
//   (ältere Routen mit {"id":"57"} = Stations-ID werden weiterhin verstanden)
// Für Start und Ziel wird jeweils die nächstgelegene BiciMAD-Station bestimmt.
// Leere Retained-Nachricht = Route gelöscht -> Profil ebenfalls löschen.
// Ausgang 1: Profil löschen | 2: ORS Fahrrad | 3: ohne ORS (Schätzung) | 4: ORS nur Fußweg
const cfg = global.get('cfg');
const R = cfg.reco;
const parts = msg.topic.split('/');
const user = parts[parts.length - 2], routeId = parts[parts.length - 1];
const key = user + '/' + routeId;
const profileTopic = cfg.prefix + '/profiles/' + key;

const empty = msg.payload === '' || msg.payload == null ||
    (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
if (empty) {
    node.status({ fill: 'grey', shape: 'dot', text: 'gelöscht: ' + key });
    return [{ topic: profileTopic, payload: '', qos: 1, retain: true }, null, null, null];
}
const r = msg.payload;
if (typeof r !== 'object' || !r.from || !r.to) {
    node.warn('Ungültige Route auf ' + msg.topic + ': ' + JSON.stringify(r));
    return null;
}
const stations = flow.get('stations');
if (!stations || Object.keys(stations).length === 0) {
    const pending = flow.get('pending') || {};
    pending[key] = msg;
    flow.set('pending', pending);
    node.status({ fill: 'yellow', shape: 'ring', text: 'warte auf Stationsliste' });
    return null;
}

// Entfernung in Metern (Näherung, für Stadtentfernungen ausreichend)
const dist = (a, b) => {
    const kx = 111320 * Math.cos(a.lat * Math.PI / 180), ky = 110540;
    return Math.hypot((a.lon - b.lon) * kx, (a.lat - b.lat) * ky);
};
// Punkt bestimmen: Koordinaten oder (alt) Stations-ID
const toPoint = (p) => {
    if (typeof p.lat === 'number' && typeof p.lon === 'number')
        return { label: p.label || p.address || (p.lat.toFixed(4) + ', ' + p.lon.toFixed(4)), address: p.address || null, lat: p.lat, lon: p.lon };
    if (p.id != null && stations[String(p.id)]) {
        const s = stations[String(p.id)];
        return { label: s.name, address: null, lat: s.lat, lon: s.lon };
    }
    return null;
};
const nearest = (pt) => {
    let best = null, bestD = Infinity;
    for (const s of Object.values(stations)) {
        const d = dist(pt, s);
        if (d < bestD) { bestD = d; best = s; }
    }
    return best;
};
const fromPoint = toPoint(r.from), toPointObj = toPoint(r.to);
if (!fromPoint || !toPointObj) {
    node.warn('Start oder Ziel ohne Koordinaten für ' + key + ': ' + JSON.stringify(r));
    return null;
}
const sFrom = nearest(fromPoint), sTo = nearest(toPointObj);
// Fußweg Adresse <-> Station: Luftlinie x Umwegfaktor (kurze Strecken, Schätzung genügt)
const leg = (a, s) => {
    const m = dist(a, s);
    return { distM: Math.round(m), walkMin: Math.round(m * R.detourFactor / 1000 / R.walkSpeedKmh * 600) / 10 };
};
const from = Object.assign({}, sFrom, leg(fromPoint, sFrom));
const to = Object.assign({}, sTo, leg(toPointObj, sTo));
const sameStation = from.id === to.id;

const source = cfg.apis.orsKey ? 'ors' : 'est';
const r4 = x => x.toFixed(4);
const routeHash = [r4(fromPoint.lat), r4(fromPoint.lon), r4(toPointObj.lat), r4(toPointObj.lon), from.id, to.id, source].join('|');
let cache = flow.get('profiles');
if (!cache || cache.__prefix !== cfg.prefix) { cache = { __prefix: cfg.prefix }; flow.set('profiles', cache); }
if (cache[key] === routeHash) {
    node.status({ fill: 'green', shape: 'ring', text: 'unverändert: ' + key });
    return null;
}
const job = {
    user: user, routeId: routeId, key: key, name: r.name || routeId,
    fromPoint: fromPoint, toPoint: toPointObj, from: from, to: to, sameStation: sameStation,
    air: dist(fromPoint, toPointObj), profileTopic: profileTopic, routeHash: routeHash
};
node.status({ fill: 'blue', shape: 'dot', text: 'berechne ' + key });
if (!cfg.apis.orsKey) return [null, null, { job: job }, null];

const headers = { 'Authorization': cfg.apis.orsKey, 'Content-Type': 'application/json', 'Accept': 'application/json' };
if (sameStation) {
    // Start und Ziel nutzen dieselbe Station: Fahrrad entfällt, nur Fußweg berechnen
    return [null, null, null, {
        job: job, url: cfg.apis.ors + '/v2/directions/foot-walking', headers: headers,
        payload: { coordinates: [[fromPoint.lon, fromPoint.lat], [toPointObj.lon, toPointObj.lat]], instructions: false }
    }];
}
// Fahrrad: von Station zu Station (dort wird das Rad geliehen und abgegeben)
return [null, {
    job: job, url: cfg.apis.ors + '/v2/directions/cycling-regular', headers: headers,
    payload: {
        coordinates: [[from.lon, from.lat], [to.lon, to.lat]],
        elevation: true,
        extra_info: ['waytype', 'steepness'],
        instructions: false
    }
}, null, null];

// Wertet die ORS-Fahrradroute aus: Länge, Dauer, Höhenmeter, Radweganteil.
// Ausgang 1: weiter zur Fußweg-Anfrage | 2: direkt zum Profil (bei Fehler)
const cfg = global.get('cfg');
const job = msg.job;
const r = msg.statusCode === 200 && msg.payload && msg.payload.routes && msg.payload.routes[0];
if (!r) {
    job.orsError = 'ORS Fahrrad: HTTP ' + msg.statusCode + ' ' +
        JSON.stringify(msg.payload && msg.payload.error || msg.payload).slice(0, 200);
    node.status({ fill: 'red', shape: 'ring', text: 'ORS-Fehler ' + msg.statusCode });
    node.warn(job.orsError);
    return [null, { job: job }];
}
const s = r.summary || {};
// Wegarten (waytype): 6 = Cycleway (Radweg). amount = Anteil in %
const wt = (r.extras && r.extras.waytype && r.extras.waytype.summary) || [];
const cycleway = wt.filter(w => w.value === 6).reduce((a, w) => a + w.amount, 0);
// Steigungsklassen (steepness): 3 = 7 bis <10 %, 4 = 10 bis <16 %, 5 = ab 16 %
const st = (r.extras && r.extras.steepness && r.extras.steepness.summary) || [];
const steep = st.filter(x => x.value >= 3).reduce((a, x) => a + x.amount, 0);
job.bike = {
    km: s.distance / 1000,
    min: s.duration / 60,
    ascent: s.ascent != null ? s.ascent : (r.ascent != null ? r.ascent : null),
    descent: s.descent != null ? s.descent : (r.descent != null ? r.descent : null),
    cyclewayPct: Math.round(cycleway),
    steepPct: Math.round(steep)
};
node.status({ fill: 'green', shape: 'dot', text: job.key + ': ' + job.bike.km.toFixed(1) + ' km' });
return [{
    job: job,
    url: cfg.apis.ors + '/v2/directions/foot-walking',
    headers: {
        'Authorization': cfg.apis.orsKey,
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    },
    payload: {
        // Fußweg komplett: von Adresse zu Adresse
        coordinates: [[job.fromPoint.lon, job.fromPoint.lat], [job.toPoint.lon, job.toPoint.lat]],
        instructions: false
    }
}, null];

// Baut das Streckenprofil und veröffentlicht es retained auf
// .../profiles/<nutzer>/<route-id>. Fehlende ORS-Daten werden geschätzt.
const cfg = global.get('cfg');
const R = cfg.reco;
const job = msg.job;

// Fußweg-Antwort von ORS (falls vorhanden)
if (typeof msg.url === 'string' && msg.url.indexOf('foot-walking') >= 0) {
    const r = msg.statusCode === 200 && msg.payload && msg.payload.routes && msg.payload.routes[0];
    if (r) job.walk = { km: r.summary.distance / 1000, min: r.summary.duration / 60 };
    else job.orsError = (job.orsError ? job.orsError + ' | ' : '') + 'ORS Fußweg: HTTP ' + msg.statusCode;
}

const r1 = x => x == null ? null : Math.round(x * 10) / 10;
const dist = (a, b) => {
    const kx = 111320 * Math.cos(a.lat * Math.PI / 180), ky = 110540;
    return Math.hypot((a.lon - b.lon) * kx, (a.lat - b.lat) * ky);
};
// Schätzungen, falls ORS fehlt
const roadKm = job.air / 1000 * R.detourFactor;
let bike = null;
if (!job.sameStation) {
    const stKm = dist(job.from, job.to) / 1000 * R.detourFactor;
    bike = job.bike || { km: stKm, min: stKm / R.bikeSpeedKmh * 60, ascent: null, descent: null, cyclewayPct: null, steepPct: null };
}
const walk = job.walk || { km: roadKm, min: roadKm / R.walkSpeedKmh * 60 };
// ÖPNV-Schätzung: Fußwege zur/von der Haltestelle + Warten + Fahrt (Straßenweg Adresse -> Adresse)
const transitMin = R.transitAccessMin + R.transitWaitMin + walk.km / R.transitSpeedKmh * 60;
const usedOrs = !!(job.bike || job.walk);
const st = s => ({ id: s.id, name: s.name, lat: s.lat, lon: s.lon, capacity: s.capacity, distM: s.distM, walkMin: s.walkMin });

const profile = {
    user: job.user,
    route: job.routeId,
    name: job.name,
    fromPoint: job.fromPoint,          // Startadresse
    toPoint: job.toPoint,              // Zieladresse
    from: st(job.from),                // nächste Station am Start (+ Fußweg dorthin)
    to: st(job.to),                    // nächste Station am Ziel (+ Fußweg von dort)
    sameStation: job.sameStation,
    bike: bike && {                    // Station -> Station
        km: r1(bike.km), min: r1(bike.min), ascent: r1(bike.ascent), descent: r1(bike.descent),
        cyclewayPct: bike.cyclewayPct, steepPct: bike.steepPct
    },
    walk: { km: r1(walk.km), min: r1(walk.min) },   // Adresse -> Adresse
    transit: { min: r1(transitMin), estimated: true },
    source: usedOrs ? 'openrouteservice' : 'Schätzung (Luftlinie)',
    orsError: job.orsError || null,
    routeHash: job.routeHash,
    computedAt: new Date().toISOString()
};
// Bei ORS-Fehler nicht cachen, damit beim nächsten Mal neu versucht wird
let cache = flow.get('profiles');
if (!cache || cache.__prefix !== cfg.prefix) cache = { __prefix: cfg.prefix };
cache[job.key] = (cfg.apis.orsKey && !usedOrs) ? null : job.routeHash;
flow.set('profiles', cache);
node.status({ fill: 'green', shape: 'dot', text: job.key + ' (' + profile.source + ')' });
return { topic: job.profileTopic, payload: profile, qos: 1, retain: true };
